effect.shader:
vec3 hue(vec3 c, float h){
    mat3 m1 = mat3(0.299,0.587,0.114, -0.14713,-0.28886,0.436, 0.615,-0.51499,-0.10001);
    mat3 m2 = mat3(1.0,0.0,1.13983, 1.0,-0.39465,-0.5806, 1.0,2.03211,0.0);
    mat3 hm = mat3(1.0,0.0,0.0, 0.0,cos(h),sin(h), 0.0,-sin(h),cos(h));
    vec3 yuv = c*m1; yuv = yuv*hm; return yuv*m2;
}
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    float h = acTime*speed*3.14159 + (acScreenNorm.x+acScreenNorm.y)*spread*3.14159;
    vec3 shifted = hue(c, h);
    float lum = dot(shifted, vec3(0.299,0.587,0.114));
    shifted = mix(vec3(lum), shifted, saturation);
    gl_FragColor = vec4(clamp(shifted,0.0,1.0),1.0)*src.a;
}
